function main(): void {
  let total = 0n;
  for (let i = 0n; i < 100n; i++) total += i * i * 2n ** 60n;
  console.log(total);
  let f = 1n;
  for (let i = 2n; i <= 30n; i++) f *= i;
  console.log(f, f.toString().length, f % 1000000007n);
  let fib0 = 0n, fib1 = 1n;
  for (let i = 0; i < 200; i++) { const t = fib0 + fib1; fib0 = fib1; fib1 = t; }
  console.log(fib0);
}
